#requires -Version 5.1
[CmdletBinding()] param([switch]$Simular)
Add-Type -AssemblyName PresentationFramework
$logDir=Join-Path $env:ProgramData 'MMachado\Otimizador\Logs'
New-Item -ItemType Directory -Path $logDir -Force -ErrorAction SilentlyContinue|Out-Null
$log=Join-Path $logDir ("Otimizador_{0:yyyyMMdd_HHmmss}.log"-f(Get-Date))
function Fmt([long]$n){if($n-ge 1GB){"{0:N2} GB"-f($n/1GB)}elseif($n-ge 1MB){"{0:N1} MB"-f($n/1MB)}elseif($n-ge 1KB){"{0:N1} KB"-f($n/1KB)}else{"$n bytes"}}
function Log([string]$m,[string]$level='INFO'){$line="{0:yyyy-MM-dd HH:mm:ss} [{1}] {2}"-f(Get-Date),$level,$m;Add-Content $log $line -Encoding UTF8;if($script:logBox){$script:logBox.AppendText($line+[Environment]::NewLine);$script:logBox.ScrollToEnd()}}
function TempFiles([string]$path,[bool]$all=$false){if(!(Test-Path $path)){return @()};$limit=(Get-Date).AddDays(-7);@(Get-ChildItem $path -File -Recurse -Force -ErrorAction SilentlyContinue|Where-Object{($all-or$_.LastWriteTime-lt$limit)-and!($_.Attributes-band[IO.FileAttributes]::ReparsePoint)})}
function TempSize([string]$path,[bool]$all=$false){[long]((TempFiles $path $all|Measure-Object Length -Sum).Sum)}
function Clean([string]$path,[string]$name,[bool]$all=$false){$sum=0L;$items=TempFiles $path $all;Log ("{0}: {1} arquivos elegiveis."-f$name,$items.Count);foreach($f in $items){try{$n=$f.Length;if(!$Simular){Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop};$sum+=$n}catch{Log ("Ignorado: "+$f.FullName) 'AVISO'}};Log ("{0} concluido: {1}."-f$name,(Fmt $sum));$sum}
function AdvancedTargets{
 $items=@(
  [pscustomobject]@{Name='Cache de shaders DirectX';Path=(Join-Path $env:LOCALAPPDATA 'D3DSCache')},
  [pscustomobject]@{Name='Despejos de falha';Path=(Join-Path $env:LOCALAPPDATA 'CrashDumps')},
  [pscustomobject]@{Name='Miniaturas e icones';Path=(Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer')},
  [pscustomobject]@{Name='Cache temporario da Internet';Path=(Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\INetCache')},
  [pscustomobject]@{Name='Relatorios de erro';Path=(Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportArchive')},
  [pscustomobject]@{Name='Fila de relatorios de erro';Path=(Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportQueue')},
  [pscustomobject]@{Name='Mini despejos do Windows';Path=(Join-Path $env:SystemRoot 'Minidump')},
  [pscustomobject]@{Name='Cache de Otimizacao de Entrega';Path=(Join-Path $env:SystemRoot 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache')}
 )
 @((Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data'),(Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\User Data'))|ForEach-Object{if(Test-Path $_){Get-ChildItem $_ -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name-eq'Default'-or$_.Name-like'Profile *'}|ForEach-Object{$profile=$_;@('Cache','Code Cache','GPUCache')|ForEach-Object{$items+=[pscustomobject]@{Name='Cache de navegador';Path=(Join-Path $profile.FullName $_)}}}}}
 $firefox=Join-Path $env:LOCALAPPDATA 'Mozilla\Firefox\Profiles';if(Test-Path $firefox){Get-ChildItem $firefox -Directory -ErrorAction SilentlyContinue|ForEach-Object{$items+=[pscustomobject]@{Name='Cache do Firefox';Path=(Join-Path $_.FullName 'cache2')}}}
 @($items|Where-Object{Test-Path -LiteralPath $_.Path}|Group-Object Path|ForEach-Object{$_.Group[0]})
}
$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Title="Otimizador - Miguel Machado" Height="640" Width="900" WindowStartupLocation="CenterScreen" Background="#F3F6FA" FontFamily="Segoe UI">
<Grid><Grid.RowDefinitions><RowDefinition Height="84"/><RowDefinition Height="*"/><RowDefinition Height="42"/></Grid.RowDefinitions>
<Border Background="#123B5D"><Grid Margin="24,9"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Otimizador de PC" Foreground="White" FontSize="26" FontWeight="SemiBold"/><TextBlock Text="Diagnostico e limpeza segura para computadores do dominio" Foreground="#CDE6F7" FontSize="14"/><TextBlock Text="by Miguel Machado" Foreground="#8FD3FF" FontSize="12" FontStyle="Italic"/></StackPanel><Border Grid.Column="1" Background="#1F567D" CornerRadius="8" Padding="14,8" VerticalAlignment="Center"><TextBlock Name="mode" Foreground="White" FontWeight="Bold"/></Border></Grid></Border>
<TabControl Grid.Row="1" Margin="18">
<TabItem Header="  Visao geral  "><Grid Margin="20"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions><TextBlock Text="Estado do computador" FontSize="22" FontWeight="SemiBold" Foreground="#123B5D"/><UniformGrid Grid.Row="1" Columns="4" Margin="0,18"><Border Background="#EAF3F8" CornerRadius="8" Margin="5" Padding="14"><StackPanel><TextBlock Text="DOMINIO"/><TextBlock Name="domain" FontSize="14" FontWeight="Bold" TextWrapping="Wrap"/></StackPanel></Border><Border Background="#EAF3F8" CornerRadius="8" Margin="5" Padding="14"><StackPanel><TextBlock Text="RAM LIVRE"/><TextBlock Name="ram" FontSize="18" FontWeight="Bold"/></StackPanel></Border><Border Background="#EAF3F8" CornerRadius="8" Margin="5" Padding="14"><StackPanel><TextBlock Text="DISCO LIVRE"/><TextBlock Name="disk" FontSize="18" FontWeight="Bold"/></StackPanel></Border><Border Background="#EAF3F8" CornerRadius="8" Margin="5" Padding="14"><StackPanel><TextBlock Text="TEMPO LIGADO"/><TextBlock Name="uptime" FontSize="18" FontWeight="Bold"/></StackPanel></Border></UniformGrid><Grid Grid.Row="2"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition/></Grid.ColumnDefinitions><GroupBox Header="Informacoes" Margin="5" Padding="12"><TextBlock Name="summary" FontFamily="Consolas" FontSize="13"/></GroupBox><GroupBox Grid.Column="1" Header="Processos com mais memoria" Margin="5"><ListView Name="processes"><ListView.View><GridView><GridViewColumn Header="Processo" Width="190" DisplayMemberBinding="{Binding Nome}"/><GridViewColumn Header="Memoria" Width="110" DisplayMemberBinding="{Binding Memoria}"/></GridView></ListView.View></ListView></GroupBox></Grid></Grid></TabItem>
<TabItem Header="  Limpeza segura  "><Grid Margin="22"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Escolha o que sera limpo" FontSize="22" FontWeight="SemiBold" Foreground="#123B5D"/><TextBlock Name="cleanInfo" Grid.Row="1" Margin="0,8,0,10" Text="Somente temporarios com mais de 7 dias. Arquivos abertos sao ignorados."/><StackPanel Grid.Row="2"><CheckBox Name="userTemp" IsChecked="True" Margin="7" FontSize="15" Content="Temporarios do usuario atual"/><CheckBox Name="winTemp" IsChecked="True" Margin="7" FontSize="15" Content="Temporarios do Windows (pode exigir administrador)"/><CheckBox Name="advanced" IsChecked="True" Margin="7" FontSize="15" FontWeight="SemiBold" Content="Limpeza avancada - caches, miniaturas, relatorios de erro e despejos"/><CheckBox Name="turbo" Margin="7" FontSize="15" FontWeight="Bold" Foreground="#B42318" Content="MODO TURBO - incluir tambem todos os temporarios recentes"/></StackPanel><Border Grid.Row="3" Background="#FFF8E1" BorderBrush="#F0CF65" BorderThickness="1" CornerRadius="8" Margin="4,10" Padding="12" VerticalAlignment="Top"><TextBlock TextWrapping="Wrap"><Run FontWeight="Bold" Text="Protecao: "/><Run Text="Documentos, Downloads, Area de Trabalho, favoritos, credenciais, rede, programas e Lixeira nao sao tocados. Arquivos em uso continuam sendo ignorados."/></TextBlock></Border><StackPanel Grid.Row="4"><ProgressBar Name="bar" Height="18" Maximum="100"/><TextBlock Name="status" Margin="0,7" Text="Pronto para analisar."/><StackPanel Orientation="Horizontal"><Button Name="analyze" Content="Analisar espaco" Width="150" Height="38" Margin="0,0,10,0"/><Button Name="clean" Content="Executar limpeza" Width="165" Height="38" Background="#167D5A" Foreground="White" FontWeight="Bold"/></StackPanel></StackPanel></Grid></TabItem>
<TabItem Header="  Registro  "><TextBox Name="logBox" Margin="18" IsReadOnly="True" FontFamily="Consolas" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap"/></TabItem>
</TabControl><Border Grid.Row="2" Background="#E1E8ED"><Grid Margin="18,0"><TextBlock Name="footer" VerticalAlignment="Center"/><Button Name="openLog" Content="Abrir logs" HorizontalAlignment="Right" Margin="0,6" Padding="14,3"/></Grid></Border></Grid></Window>
'@
$window=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$xaml)))
@('mode','domain','ram','disk','uptime','summary','processes','userTemp','winTemp','advanced','turbo','cleanInfo','bar','status','analyze','clean','logBox','footer','openLog')|ForEach-Object{Set-Variable -Name $_ -Value $window.FindName($_) -Scope Script}
$mode.Text=if($Simular){'MODO SIMULACAO'}else{'MODO NORMAL'};$footer.Text="by Miguel Machado  |  Log: $log"
function Dashboard{try{$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$d=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'";$up=(Get-Date)-$os.LastBootUpTime;$dom=if($cs.PartOfDomain){$cs.Domain}else{'Fora de dominio'};$domain.Text=$dom;$ram.Text=Fmt([long]$os.FreePhysicalMemory*1KB);$disk.Text=Fmt([long]$d.FreeSpace);$uptime.Text=("{0}d {1}h"-f$up.Days,$up.Hours);$summary.Text=("Computador : {0}{1}Windows    : {2}{1}RAM total  : {3}{1}Disco C:   : {4} livres de {5}"-f$env:COMPUTERNAME,[Environment]::NewLine,$os.Caption,(Fmt([long]$cs.TotalPhysicalMemory)),(Fmt([long]$d.FreeSpace)),(Fmt([long]$d.Size)));$processes.Items.Clear();Get-Process -ErrorAction SilentlyContinue|Sort-Object WorkingSet64 -Descending|Select-Object -First 8|ForEach-Object{[void]$processes.Items.Add([pscustomobject]@{Nome=$_.ProcessName;Memoria=Fmt $_.WorkingSet64})};Log ("Diagnostico atualizado; dominio: "+$dom)}catch{Log ("Falha no diagnostico: "+$_.Exception.Message) 'ERRO'}}
$turbo.Add_Checked({$cleanInfo.Text='MODO TURBO ativo: todos os temporarios e caches recentes tambem serao selecionados.';$clean.Background='#B42318';$clean.Content='Executar TURBO';Log 'Modo Turbo ativado.'})
$turbo.Add_Unchecked({$cleanInfo.Text='Somente temporarios com mais de 7 dias. Arquivos abertos sao ignorados.';$clean.Background='#167D5A';$clean.Content='Executar limpeza'})
$analyze.Add_Click({$bar.Value=15;$status.Text='Analisando...';$window.Dispatcher.Invoke([action]{},'Background');$total=0L;$all=[bool]$turbo.IsChecked;if($userTemp.IsChecked){$total+=TempSize $env:TEMP $all};if($winTemp.IsChecked){$total+=TempSize (Join-Path $env:SystemRoot 'Temp') $all};$bar.Value=55;if($advanced.IsChecked){AdvancedTargets|ForEach-Object{$total+=TempSize $_.Path $all}};$bar.Value=100;$status.Text=("Espaco potencial: "+(Fmt $total));Log $status.Text})
$clean.Add_Click({if(!$userTemp.IsChecked-and!$winTemp.IsChecked-and!$advanced.IsChecked){[System.Windows.MessageBox]::Show('Selecione uma opcao.','Otimizador')|Out-Null;return};$all=[bool]$turbo.IsChecked;$action=if($Simular){'simular a limpeza'}else{'remover os temporarios e caches selecionados'};$question="Deseja "+$action+" agora?"+[Environment]::NewLine+[Environment]::NewLine+"Nenhum arquivo pessoal sera afetado.";if([System.Windows.MessageBox]::Show($question,'Confirmar','YesNo','Question')-ne'Yes'){return};if($all-and !$Simular){$warning='MODO TURBO: temporarios e caches recentes tambem serao apagados. Feche os aplicativos para uma limpeza mais completa. Confirma novamente?';if([System.Windows.MessageBox]::Show($warning,'Confirmacao do Modo Turbo','YesNo','Warning')-ne'Yes'){return}};$clean.IsEnabled=$false;$analyze.IsEnabled=$false;try{$total=0L;if($userTemp.IsChecked){$total+=Clean $env:TEMP 'Temporarios do usuario' $all};if($winTemp.IsChecked){$total+=Clean (Join-Path $env:SystemRoot 'Temp') 'Temporarios do Windows' $all};$bar.Value=55;$window.Dispatcher.Invoke([action]{},'Background');if($advanced.IsChecked){AdvancedTargets|ForEach-Object{$total+=Clean $_.Path $_.Name $all}};$bar.Value=100;$label=if($Simular){'Estimativa'}else{'Liberado'};$status.Text=("{0}: {1}"-f$label,(Fmt $total));[System.Windows.MessageBox]::Show($status.Text,'Otimizador')|Out-Null;Dashboard}catch{Log ("Erro: "+$_.Exception.Message) 'ERRO'}finally{$clean.IsEnabled=$true;$analyze.IsEnabled=$true}})
$openLog.Add_Click({Start-Process explorer.exe -ArgumentList $logDir})
Log ("Otimizador by Miguel Machado iniciado. Simulacao: "+$Simular);Dashboard;[void]$window.ShowDialog()
